import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.2
.target sm_89
.address_size 64

.visible .entry ts_matmul(
    .param .u64 pA,
    .param .u64 pB,
    .param .u64 pC
)
{
    .reg .pred %prow, %pcol, %p, %pk;
    .reg .b32 %tidx, %ctax, %row, %col0, %col3, %k, %r, %aoff, %boff, %coff;
    .reg .b64 %A, %B, %C, %addr;
    .reg .f32 %acc0, %acc1, %acc2, %acc3, %fa, %fb0, %fb1, %fb2, %fb3;

    ld.param.u64 %A, [pA];
    ld.param.u64 %B, [pB];
    ld.param.u64 %C, [pC];

    mov.u32 %tidx, %tid.x;
    mov.u32 %ctax, %ctaid.x;
    mov.u32 %row, %ctaid.y;

    shl.b32 %r, %ctax, 8;
    add.u32 %r, %r, %tidx;
    shl.b32 %col0, %r, 2;
    add.u32 %col3, %col0, 3;

    setp.lt.u32 %prow, %row, 32768;
    setp.lt.u32 %pcol, %col3, 32768;
    and.pred %p, %prow, %pcol;

    mov.f32 %acc0, 0f00000000;
    mov.f32 %acc1, 0f00000000;
    mov.f32 %acc2, 0f00000000;
    mov.f32 %acc3, 0f00000000;
    mov.u32 %k, 0;

K_LOOP:
    setp.lt.u32 %pk, %k, 32;
    @!%pk bra K_DONE;

    shl.b32 %r, %row, 5;
    add.u32 %aoff, %r, %k;
    mad.wide.u32 %addr, %aoff, 4, %A;
    mov.f32 %fa, 0f00000000;
    @%prow ld.global.f32 %fa, [%addr];

    shl.b32 %r, %k, 15;
    add.u32 %boff, %r, %col0;
    mad.wide.u32 %addr, %boff, 4, %B;
    mov.f32 %fb0, 0f00000000;
    mov.f32 %fb1, 0f00000000;
    mov.f32 %fb2, 0f00000000;
    mov.f32 %fb3, 0f00000000;
    @%pcol ld.global.v4.f32 {%fb0, %fb1, %fb2, %fb3}, [%addr];

    fma.rn.f32 %acc0, %fa, %fb0, %acc0;
    fma.rn.f32 %acc1, %fa, %fb1, %acc1;
    fma.rn.f32 %acc2, %fa, %fb2, %acc2;
    fma.rn.f32 %acc3, %fa, %fb3, %acc3;

    add.u32 %k, %k, 1;
    bra K_LOOP;

K_DONE:
    shl.b32 %r, %row, 15;
    add.u32 %coff, %r, %col0;
    mad.wide.u32 %addr, %coff, 4, %C;
    @%p st.global.v4.f32 [%addr], {%acc0, %acc1, %acc2, %acc3};
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("ts_matmul")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        out = torch.empty((A.shape[0], B.shape[1]), dtype=A.dtype, device=A.device)
        _get_ptx_module().launch(
            "ts_matmul",
            grid=(32, 32768, 1),
            block=(256, 1, 1),
            arguments=[A, B, out],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return out

